Definition source_AST_133_0003 := row_to_tm [t0LB;t1LA;t1RC;t0LA;t1RD;t0RB;t1LB;t0RB].
Definition perm_AST_133_0003(q:St):St := match q with StA=>StD | StB=>StC | StC=>StA | StD=>StB end.
Definition skip_AST_133_0003(t:Instr):bool := instr_eqb t (StA,S1).

(* spec 0RB1RA_1LC0RA_1LD0LB_1RB0LB *)
Definition r_AST_133_0000 : list (option Trans) := [t0RB;t1RA;t1LC;t0RA;t1LD;t0LB;t1RB;t0LB].
Lemma cv_AST_133_0000 : coversTr (row_to_tm r_AST_133_0000).
Proof. assert(Hhit:finite_instr_hit(row_to_tm r_AST_133_0000)(StC,S1)).
  { apply(finite_instr_conjugate source_AST_133_0000 _ perm_AST_133_0000 true (StC,S1)).
    - intros[] [];reflexivity.
    - intros[];first[exists StA;reflexivity|exists StB;reflexivity|
                    exists StC;reflexivity|exists StD;reflexivity].
    - intro c. apply ts_finite;reflexivity. }
  assert(Htotal:forall q s,exists tr,row_to_tm r_AST_133_0000 q s=Some tr)
    by(intros[] [];eexists;reflexivity).
  pose proof(finite_instr_recurrent _ _ Htotal Hhit)as Hrec.
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 1984 18
    skip_AST_133_0000 cert_AST_133_0000).
  - intros[[] []] H N;try discriminate.
    destruct(Hrec N)as(j&Hj&Hf). exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

